def count_distinct_sums(N):
    """
    Calculates the number of distinct sums s = i + j where 0 <= i <= j <= N.
    For a set {0, 1, ..., N}, the sums cover all integers from 0 to 2N.
    """
    sums = set()
    for i in range(N + 1):
        for j in range(i, N + 1):
            sums.add(i + j)
    return len(sums)

