def solve_small_fast(n, M):
    # We need to minimize |A+A| where A is a subset of {0, ..., M} of size n.
    # This is a known problem. The smallest sumset size for a given n and M
    # can be found by looking for sets A that are "as close as possible" to an AP.
    # Let's try some candidate sets.

    def get_sumset_size(A):
        sums = set()
        for i in range(len(A)):
            for j in range(i, len(A)):
                sums.add(A[i] + A[j])
        return len(sums)

    min_size = float('inf')

    # Strategy 1: AP with some elements modified.
    # Try all possible common differences d.
    for d in range(1, M + 1):
        # If d is the common difference, the terms are 0, d, 2d, ..., (n-1)d.
        # But we need the max element to be M.
        # So we could take an AP with difference d and shift it,
        # or adjust some elements.
        # Let's try a simple approach:
        # A = {0, d, 2d, ..., (n-2)d, M}
        if (n-2)*d <= M:
            A = [i*d for i in range(n-1)] + [M]
            min_size = min(min_size, get_sumset_size(A))

        # A = {0, d, 2d, ..., (n-3)d, M-d, M}
        if (n-3)*d <= M-d:
            A = [i*d for i in range(n-2)] + [M-d, M]
            min_size = min(min_size, get_sumset_size(A))

        # A = {0, d, 2d, ..., (n-k)d, M-(k-1)d, ..., M-d, M}
        # This is like taking an AP and replacing the last k elements with
        # a "dense" block at the end.
        for k in range(2, n):
            if (n-k)*d <= M - (k-1)*d:
                # The first n-k elements are 0, d, 2d, ..., (n-k-1)d
                # The last k elements are M-(k-1)d, M-(k-2)d, ..., M
                # But we need to be careful. Let's just try small k.
                A = [i*d for i in range(n-k)] + list(range(M-(k-1)*d, M+1))
                # Wait, the last k elements must be distinct and not in the first part.
                # Also their values must be in increasing order.
                # Let's just construct it carefully.
                A = [i*d for i in range(n-k)]
                last_part = list(range(M-(k-1)*d, M+1))
                A.extend(last_part)
                if len(set(A)) == n:
                    min_size = min(min_size, get_sumset_size(A))
    return min_size

