def solve_small_fast_v2(n, M):
    def get_sumset_size(A):
        sums = set()
        for i in range(len(A)):
            for j in range(i, len(A)):
                sums.add(A[i] + A[j])
        return len(sums)

    min_size = float('inf')

    # The minimum sumset size is always achieved by a set that is "almost" an AP.
    # It is often a union of two APs with the same common difference.
    # Or an AP with some elements changed.

    for d in range(1, M + 1):
        # Try A = {0, d, 2d, ..., (n-k-1)d, M-(k-1)d, ..., M}
        # This is a union of two APs with common difference d.
        # The first AP is {0, d, ..., (n-k-1)d} (size n-k)
        # The second AP is {M-(k-1)d, M-(k-2)d, ..., M} (size k)
        for k in range(1, n + 1):
            # Need n-k >= 0 and k >= 1. Wait, n-k can be 0.
            # If k=n, A = {M, M-d, M-2d, ..., M-(n-1)d} but we need 0 in A.
            # So if k=n, A must be {0, d, 2d, ..., (n-1)d} and M = (n-1)d.
            if k == n:
                if M == (n-1)*d:
                    A = [i*d for i in range(n)]
                    min_size = min(min_size, get_sumset_size(A))
                continue

            # If 0 < k < n
            # The first AP has n-k elements: {0, d, 2d, ..., (n-k-1)d}
            # The second AP has k elements: {M-(k-1)d, M-(k-2)d, ..., M}
            # We need these two sets to be disjoint and their union to have n elements.
            # The max of the first is (n-k-1)d. The min of the second is M-(k-1)d.
            # We need (n-k-1)d < M-(k-1)d.
            # Wait, the elements must be strictly increasing.
            # Let's just construct and check.
            A = [i*d for i in range(n-k)]
            last_part = list(range(M-(k-1)*d, M+1, -d))
            last_part.reverse()
            A.extend(last_part)

            # Check if A is valid
            if len(set(A)) == n and A == sorted(list(set(A))) and A[0] == 0 and A[-1] == M:
                min_size = min(min_size, get_sumset_size(A))
    return min_size

